// booth_ctrl_mealy.sv - Mealy controller of the skip-capable Booth multiplier.
// Generated by scripts/emit_sv.py from scripts/fsms.py - do not edit by hand.
// Flip-flops: SR, logic: minimal POS (exact two-level minimisation with don't-cares),
// next-state 6 two-input gates, outputs 5 two-input gates.
// State encoding:
//   INIT   = 00
//   A      = 01
//   B      = 11
//   END    = 10
// EX_OP is a don't-care once COMPLETED is high (the datapath is frozen) and in END.

module booth_ctrl_mealy (
  input  logic       clk,
  input  logic       rst,           // synchronous, to INIT
  input  logic       shift_in,      // multiplier bit 0 (the bit just entering the window)
  input  logic       completed,     // all shifts done: go to END
  output logic [1:0] ex_op,         // 00 init, 01 add, 10 subtract, 11 shift
  output logic       done
);
  logic [1:0] q, qn;
  logic r0, r1, s0, s1;
  logic ex1, ex0;
  assign s1     = q[0] & (shift_in | completed);  // 2 gates
  assign r1     = q[0] & ~completed & ~shift_in;  // 2 gates
  assign s0     = qn[0] & qn[1];  // 1 gates
  assign r0     = q[0] & completed;  // 1 gates
  assign ex1    = q[0] & (qn[1] | shift_in);  // 2 gates
  assign ex0    = q[0] & (q[1] | ~shift_in);  // 2 gates
  assign done   = q[1] & qn[0];  // 1 gates

  sr_ff u_q1 (.clk, .s(s1 & ~rst), .r(r1 | rst), .q(q[1]), .qn(qn[1]));
  sr_ff u_q0 (.clk, .s(s0 & ~rst), .r(r0 | rst), .q(q[0]), .qn(qn[0]));
  assign ex_op = {ex1, ex0};
endmodule
